function [h] = total_momentum(x, inertia, m, f)
%TOTAL_MOMENTUM  The total angular momentum [N m s], body axes, of the state x.
%   x: PlantState (passed rec)
%   inertia: real[1][3][3] (passed a plain number)
%   m: RotorGeometry (passed rec)
%   f: Flex (passed rec)
%   returns h: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    h = zeros(3, 1);
    a = asils.models.rotors.rotor_axes(m, x.d);
    h = [inertia(1, 1)*x.w(1) + inertia(1, 2)*x.w(2) + inertia(1, 3)*x.w(3); inertia(2, 1)*x.w(1) + inertia(2, 2)*x.w(2) + inertia(2, 3)*x.w(3); inertia(3, 1)*x.w(1) + inertia(3, 2)*x.w(2) + inertia(3, 3)*x.w(3)];
    for ir = (0):((m.nr) - 1)
        k = ((0):((3) - 1)).';
        h((k) + 1) = (reshape(h((k) + 1), [], 1) + ((a((ir) + 1, (k) + 1)).' .* x.h((ir) + 1)));
    end
    if f.on
        k2 = ((0):((3) - 1)).';
        h((k2) + 1) = (reshape(h((k2) + 1), [], 1) + (reshape(f.delta((k2) + 1), [], 1) .* x.etad));
    end
end
